package ru.opodoydet.accounts.listings;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.Instant;
import ru.opodoydet.accounts.AccountProblem;
import ru.opodoydet.domain.Amenities;
import ru.opodoydet.domain.Features;
import ru.opodoydet.shared.Json;

/** Owner-entered public fields, with provenance generated by the server, not the client. */
public final class ListingAmenities {
  private ListingAmenities() {}

  static void apply(ObjectNode listing, JsonNode input, JsonNode existing) {
    ObjectNode evidence = existing != null && existing.path("amenityEvidence").isObject()
        ? existing.path("amenityEvidence").deepCopy() : Json.obj();
    if (input.has("amenityStates")) {
      JsonNode states = input.path("amenityStates");
      if (!states.isObject() || states.size() > Amenities.patterns().size())
        throw new AccountProblem(400, "Укажите удобства отдельными значениями: есть, нет или неизвестно.");
      states.fields().forEachRemaining(entry -> {
        String feature = entry.getKey();
        JsonNode value = entry.getValue();
        if (!Amenities.contains(feature) || !(value.isBoolean() || value.isNull()))
          throw new AccountProblem(400, "Неизвестное удобство или неверное значение.");
        // Omitting a field preserves it; explicit null clears the old claim.
        if (!evidence.has(feature) || !evidence.path(feature).path("value").equals(value))
          evidence.set(feature, Json.obj("value", value, "source", "owner",
              "method", "structured_owner_declaration", "scope", Features.get(feature).scope(),
              "obtainedAt", Instant.now().toString(), "sourceDate", null));
      });
    }
    listing.set("amenityEvidence", evidence);
    listing.set("amenityStates", states(evidence));
  }

  public static ObjectNode states(JsonNode evidence) {
    ObjectNode states = Json.obj();
    for (String id : Amenities.definitions().keySet()) {
      JsonNode value = evidence.path(id).path("value");
      if (value.isBoolean()) states.set(id, value);
      else states.putNull(id);
    }
    return states;
  }
}
